using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1DetailCheck {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";static string Out=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_DetailPass/");
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var before=JArray.Parse(File.ReadAllText(Out+"before_transforms.json"));var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var map=ts.ToDictionary(t=>AnimationUtility.CalculateTransformPath(t,null));var changes=new List<string>();float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 foreach(var b in before){string path=(string)b["path"];if(!map.TryGetValue(path,out var t)){changes.Add(path+" missing");continue;}foreach(var q in new[]{new{key="position",value=V(t.position)},new{key="local",value=V(t.localPosition)},new{key="rotation",value=V(t.localEulerAngles)},new{key="scale",value=V(t.localScale)}}){var a=b[q.key].Values<float>().ToArray();if(q.value.Where((v,i)=>Mathf.Abs(v-a[i])>.00001f).Any())changes.Add(path+" "+q.key);}if((bool)b["active"]!=t.gameObject.activeSelf)changes.Add(path+" active");var cc=t.GetComponents<Collider>();if(cc.Length!=b["colliders"].Count())changes.Add(path+" collider count");}
 var parents=JArray.Parse(File.ReadAllText(Out+"apply.json"));var attachmentErrors=new List<string>();foreach(var q in parents){string path=(string)q["parent"]+"/"+(string)q["name"];if(!map.ContainsKey(path)){attachmentErrors.Add(path+" missing");continue;}var t=map[path];if(t.localPosition!=Vector3.zero||t.localRotation!=Quaternion.identity||t.localScale!=Vector3.one)attachmentErrors.Add(path+" local offset");if((bool)q["dynamic"]&&t.GetComponentsInChildren<Transform>().Any(a=>GameObjectUtility.GetStaticEditorFlags(a.gameObject)!=0))attachmentErrors.Add(path+" static moving detail");}
 var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"AEWeatheredLit.shader");var sm=ShaderUtil.GetShaderMessages(shader).Select(m=>new{m.message,severity=m.severity.ToString(),m.line}).ToArray();var lodErrors=new List<string>();foreach(var t in ts){var group=t.GetComponent<LODGroup>();if(!group)continue;var lod=group.GetLODs();if(lod.Any(l=>l.renderers.Any(r=>!r)))lodErrors.Add(t.name+" null renderer");if(t.name.StartsWith("FD_")&&lod.Length!=3)lodErrors.Add(t.name+" not 3 LODs");}
 var r=new{scene=s.path,saved=!s.isDirty,playing=Application.isPlaying,runInBackground=Application.runInBackground,beforeTransforms=before.Count,transforms=ts.Length,addedTransforms=ts.Length-before.Count,transformChanges=changes,detailInstances=parents.Count,attachmentErrors,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),missingMeshes=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh),missingMaterials=ts.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader)),shaderMessages=sm,shaderErrors=sm.Count(m=>m.severity=="Error"),lodErrors,occlusionBytes=StaticOcclusionCulling.umbraDataSize};File.WriteAllText(Out+"final_check.json",JsonConvert.SerializeObject(r,Formatting.Indented));Selection.activeGameObject=GameObject.Find("F1_VL_LiftAssembly");SceneView.lastActiveSceneView?.LookAt(new Vector3(44,1.8f,28.4f),Quaternion.Euler(3,0,0),4.8f,false,true);return r;}
 public static object Movement(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var lift=GameObject.Find("F1_VL_LiftAssembly").transform;var car=lift.Find("Car");var cw=lift.Find("Counterweight");var sheave=lift.Find("Sheave");var a=car.Find("FD_LiftCar");var b=cw.Find("FD_LiftCounterweight");var fixedPart=lift.Find("FixedShaft/FD_LiftGuides");var fixedBefore=fixedPart.position;bool carFollow=false,weightFollow=false,fixedStayed=false,wheelFollow=false;try{var ap=a.position;var bp=b.position;car.localPosition+=Vector3.down*9;cw.localPosition+=Vector3.up*9;sheave.localRotation=Quaternion.Euler(0,0,-9/1.2f*Mathf.Rad2Deg);carFollow=Vector3.Distance(a.position,ap+Vector3.down*9)<.0001f;weightFollow=Vector3.Distance(b.position,bp+Vector3.up*9)<.0001f;fixedStayed=fixedPart.position==fixedBefore;wheelFollow=Quaternion.Angle(sheave.Find("FD_LiftSheave").rotation,sheave.rotation)<.001f;}finally{EditorSceneManager.OpenScene(s.path);}var r=new{carFollow,weightFollow,fixedStayed,wheelFollow,temporaryPoseRestored=true,gameplayCodeAdded=0};File.WriteAllText(Out+"moving_parts.json",JsonConvert.SerializeObject(r,Formatting.Indented));return r;}
}
